function updateEditorZoom(event,commit=false){const raw=event.target.value,next=boundedNumber(raw,25,300);if(next===null||!commit&&(Number(raw)<25||Number(raw)>300))return;studio.setZoom(next);if(commit)event.target.value=String(next);}
function themeHex(event,key,commit=true){const value=event.target.value;if(/^#[\da-f]{6}$/i.test(value))studio.themeEditor.value[key]=value;else if(commit){event.target.value=studio.themeEditor.value[key];studio.notify('Couleur au format #RRGGBB.');}}
