udes(view)&&selected&&!studio.animation?.preview.value&&!studio.animation?.engine.value&&!studio.selectionLocked" class="rotation-handle" :style="rotationHandle" aria-label="Tourner l’élément" title="Tourner · Maj : pas de 45°" @pointerdown.stop="rotateDown" @pointermove.stop="move" @pointerup.stop="up" @pointercancel.stop="up">↻</button>
