    <PedagogicalBar v-if="!studio.isAnimation&&!presenting&&['slides','banners'].includes(view)&&!studio.isThumbnail&&workspace==='editor'" :studio="studio"/><div class="canvas-bottom editor-bottom" v-if="!presenting"><div class="bottom-tools"><button class="icon-btn" :disabled="!studio.canUndo.value" @click="studio.undo" aria-label="Annuler" title="Annuler · Ctrl Z"><Undo2 :size="17"/></button><button class="icon-btn" :disabled="!studio.canRedo.value" @click="studio.redo" aria-label="Rétablir" title="Rétablir · Ctrl Maj Z"><Redo2 :size="17"/></button><span class="divider"></span><button class="icon-btn" :class="{active:panels.snapping}" :aria-pressed="!!panels.snapping" aria-label="Aimantation" @click="panels.snapping=!panels.snapping" title="Aimantation : aligner automatiquement les objets"><Magnet :size="17"/></button><button class="icon-btn" :class="{active:altHeld}" :aria-pressed="altHeld" aria-label="Repères de distance" @click="altHeld=!altHeld" title="Repères de distance · Alt"><Ruler :size="17"/></button></div><div class="bottom-zoom"><button class="icon-btn" @click="studio.setZoom(zoom-10)" title="Dézoomer" aria-label="Dézoomer"><Minus :size="16"/></button><label class="number-unit"><input type="number" :value="zoom" min="25" max="300" step="1" aria-label="Zoom de l’éditeur" @input="updateEditorZoom" @change="updateEditorZoom($event,true)" @keydown.enter="updateEditorZoom($event,true)"><span>%</span></label><button class="icon-btn" @click="studio.setZoom(zoom+10)" title="Zoomer" aria-label="Zoomer"><Plus :size="16"/></button><button class="icon-btn" @click="studio.setZoom(100);studio.animation&&(studio.animation.panX.value=0,studio.animation.panY.value=0)" title="Revenir à 100 %" aria-label="Revenir à 100 %"><Maximize2 :size="16"/></button></div><div v-if="view==='slides'&&!studio.isThumbnail" class="bottom-pages"><button class="icon-btn" @click="navigate(-1)" :disabled="index===0" title="Diapo précédente"><ChevronLeft :size="16"/></button><span>{{index+1}} <span class="muted">/ {{slides.length}}</span></span><button class="icon-btn" @click="navigate(1)" :disabled="index===slides.length-1" title="Diapo suivante"><ChevronRight :size="16"/></button></div></div>
