<div v-if="videoPreview&&lastExport?.video" class="export-backdrop" @click.self="videoPreview=false"><section class="export-dialog" role="dialog" aria-modal="true" aria-label="Votre enregistrement"><div class="export-heading"><div><strong>Ton enregistrement est prêt.</strong><p>{{lastExport.size}} Ko · {{lastExport.playable?'WebM':lastExport.name.endsWith('.mkv')?'MKV · FFV1':'MOV · QTRLE'}} <span v-if="videoMeta">· {{videoMeta}}</span></p></div><button class="icon-btn" @click="videoPreview=false" title="Fermer l’aperçu"><X :size="20"/></button></div><p v-if="!lastExport.playable" class="field-help">Vidéo sans perte prête pour le montage. L’aperçu de ce codec n’est pas disponible dans tous les navigateurs. Capture limitée à 256 Mo, fichier encodé à 512 Mo ; pour une longue prise, privilégie une résolution réduite ou WebM.</p><video v-else :src="lastExport.url" controls @loadedmetadata="videoMeta=$event.target.videoWidth+' × '+$event.target.videoHeight"/><a class="btn primary" :href="lastExport.url" :download="lastExport.name"><Download :size="16"/>Télécharger la vidéo</a></section></div>
<a v-if="lastExport&&!videoPreview&&!presenting" class="last-export" :href="lastExport.url" :download="lastExport.name"><Download :size="15"/>{{lastExport.name}} · {{lastExport.size}} Ko</a>
  <div v-if="formatOpen" class="modal-backdrop" @click.self="formatOpen=false"><section class="format-dialog" role="dialog" aria-modal="true" aria-label="Format du projet"><h2>Format du projet</h2><p>Ce document utilise ce format 16:9.</p><select v-model.number="formatWidth" aria-label="Résolution"><option :value="1280">HD · 1280 × 720</option><option :value="1920">Full HD · 1920 × 1080</option><option :value="2560">QHD · 2560 × 1440</option><option :value="3840">4K · 3840 × 2160</option></select><label>Largeur personnalisée<input type="number" v-model.number="formatWidth" min="640" max="3840" step="16"></label><p>Hauteur : {{formatWidth*9/16}} px</p><button class="btn" @click="formatOpen=false">Annuler</button><button class="btn primary" @click="applyFormat">Appliquer</button></section></div><div v-if="contextMenu" class="element-context" role="menu" :style="{left:contextMenu.x+'px',top:contextMenu.y+'px'}" @pointerdown.stop>
 <template v-if="contextMenu.element"><button v-if="!['image','shape','bits'].includes(selectedType)" role="menuitem" @click="dismissContext();editSelected()">Éditer le contenu <span>Double-clic</span></button><button role="menuitem" @click="studio.copySelection();dismissContext()">Copier <span>Ctrl C</span></button><button role="menuitem" @click="duplicateSelected">Dupliquer <span>Ctrl D</span></button><button role="menuitem" @click="removeBlock" >Supprimer</button><hr></template>
 <details v-if="studio.isAnimation" class="engine-context-submenu"><summary>Ajouter un moteur</summary><button role="menuitem" @click="studio.animation.addEngine('particles',contextMenu.scenePoint);dismissContext()">Moteur à particules</button><button role="menuitem" @click="studio.animation.addEngine('gravity',contextMenu.scenePoint);dismissContext()">Moteur de gravité</button></details><button role="menuitem" @click="dismissContext();addBlock('text')">Ajouter un texte</button><button role="menuitem" @click="dismissContext();addBlock('image')">Ajouter une image</button><button role="menuitem" @click="dismissContext();addBlock('code')">Ajouter du code</button><button role="menuitem" @click="openShapes">Ajouter une forme</button><button role="menuitem" @click="dismissContext();addBlock('table')">Ajouter un tableau</button>
</div><AnimationPreview v-if="studio.animation?.previewOpen.value" :studio="studio"/><VideoEncodingRecovery :encoding="studio.videoEncoding"/>
</template>
